INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q17633452', 'First Central American Civil War', 'The First Central American Civil War (Spanish: Primera Guerra Civil Centroamericana), also known as the Federal War of 1826–1829 (Guerra Federal de 1826–1829), was a civil political and military conflict within the Federal Republic of Central America which lasted from 1826 until 1829. The civil war was fought between liberals led by General Francisco Morazán and conservatives led by General Manuel José Arce, the president of Central America and a former liberal.', 1826, 9, 6, 1829, 6, 25, 'day', '6 September 1826 – 25 June 1829', 37, 'https://en.wikipedia.org/wiki/First_Central_American_Civil_War'),
  ('Q5027839', 'Filibuster War', 'The Filibuster War, also referred to the Walker affair and known in Costa Rica as the National Campaign of 1856–1857, was a war fought in Central America between 1855 and 1857. The militaries of Costa Rica, El Salvador, Guatemala, Honduras, and Nicaragua established the Allied Central American Army and fought against American filibusters led by William Walker who had taken over the Nicaraguan government.', 1855, 6, 16, 1857, 5, 1, 'day', '16 June 1855 – 1 May 1857', 37, 'https://en.wikipedia.org/wiki/Filibuster_War'),
  ('Q7443116', 'Second Battle of Rivas', 'The Second Battle of Rivas occurred on 11 April 1856 between Costa Rican militia under General Juan Rafael Mora Porras and the Nicaraguan forces of American mercenary William Walker. The lesser known First Battle of Rivas took place on the 29 June 1855 between Walker''s forces and the forces of the Chamorro government of Nicaragua.', 1856, 4, 11, NULL, NULL, NULL, 'day', '11 April 1856', 34, 'https://en.wikipedia.org/wiki/Second_Battle_of_Rivas'),
  ('Q7837136', 'Treaty of Managua', 'The Treaty of Managua, also known as the Zeledon–Wyke treaty, was an 1860 agreement between the United Kingdom and Nicaragua, in which Britain recognised Nicaraguan sovereignty over the Kingdom of Mosquitia, but reserved, on the basis of historical rights, a self-governing enclave known of the Mosquito Reservation for the people, citing earlier treaty arrangements and historical circumstances. The question was referred for arbitration to the Emperor of Austria, Franz Joseph I, whose award, published on 2 July 1881, upheld the contention of the native inhabitants, and affirmed that the…', 1860, 1, 28, NULL, NULL, NULL, 'day', '28 January 1860', 37, 'https://en.wikipedia.org/wiki/Treaty_of_Managua'),
  ('Q5918797', 'Barrios'' War of Reunification', 'Barrios'' War of Reunification, also known as Barrios'' great attempt (Spanish: intentona de Barrios), was a war initiated by Guatemalan President Justo Rufino Barrios in 1885 with the goal of reunifying Central America. Of the five Central American countries, only Honduras supported Barrios'' reunification effort; Costa Rica, El Salvador, and Nicaragua opposed it, as did Mexico.', 1885, 2, 28, 1885, 4, 14, 'day', '28 February 1885 – 14 April 1885', 26, 'https://en.wikipedia.org/wiki/Barrios''_War_of_Reunification'),
  ('Q2304042', 'United States occupation of Nicaragua', 'The United States occupation of Nicaragua from August 4, 1912, to January 2, 1933, was part of the Banana Wars, when the U.S. military invaded various Latin American countries from 1898 to 1934. The formal occupation began on August 4, 1912, even though there were various other assaults by the United States in Nicaragua throughout this period.', 1912, NULL, NULL, 1933, NULL, NULL, 'year', '1912–1933', 55, 'https://en.wikipedia.org/wiki/United_States_occupation_of_Nicaragua'),
  ('Q3636296', 'Battle of Coyotepe Hill', 'The Battle of Coyotepe Hill was a significant engagement during the United States occupation of Nicaragua from August through November 1912 during the insurrection staged by Minister of War General Luis Mena against the government of President Adolfo Díaz. Coyotepe is an old fortress located on a 500-foot hill overlooking the strategic railroad line near Masaya roughly halfway between Managua and Granada, Nicaragua.', 1912, 10, 3, 1912, 10, 4, 'day', '3 October 1912 – 4 October 1912', 37, 'https://en.wikipedia.org/wiki/Battle_of_Coyotepe_Hill'),
  ('Q1553256', 'Nicaraguan Civil War of 1926–1927', 'The Nicaraguan Civil War of 1926–1927, or the Constitutionalist War, broke out after a coup d''état by Emiliano Chamorro, a member of the Conservative Party, removed Nicaragua''s democratically elected government, resulting in a rebellion by members of the Liberal Party. The conflict came to an end after a military and diplomatic intervention by the United States resulted in the Pact of Espino Negro, which began the Peace of Tipitapa.', 1926, 5, 2, 1927, 5, 4, 'day', '2 May 1926 – 4 May 1927', 41, 'https://en.wikipedia.org/wiki/Nicaraguan_Civil_War_(1926%E2%80%931927)'),
  ('Q4562866', '1931 Nicaragua earthquake', 'The 1931 Nicaragua earthquake devastated Nicaragua''s capital city of Managua on 31 March 1931. It had a moment magnitude of 6.1 and a maximum MSK intensity of VI (Strong).', 1931, 3, 31, NULL, NULL, NULL, 'day', '31 March 1931', 39, 'https://en.wikipedia.org/wiki/1931_Nicaragua_earthquake'),
  ('Q10861134', '1956 Nicaragua earthquake', 'The 1956 Nicaragua earthquake occurred on October 24 at 14:42 UTC. The epicenter was located west of Masachapa, Managua Department, Nicaragua. It was an earthquake of magnitude Ms 7.3, or Mw 7.2.', 1956, 10, 24, NULL, NULL, NULL, 'day', '24 October 1956', 34, 'https://en.wikipedia.org/wiki/1956_Nicaragua_earthquake'),
  ('Q924446', '1972 Nicaragua earthquake', 'The 1972 Nicaragua earthquake occurred at 12:29:44 a.m. local time (06:29:44 UTC) on 23 December near Managua, the capital of Nicaragua.', 1972, 12, 23, NULL, NULL, NULL, 'day', '23 December 1972', 53, 'https://en.wikipedia.org/wiki/1972_Nicaragua_earthquake'),
  ('Q1463516', 'Nicaraguan Revolution', 'The Nicaraguan Revolution (Spanish: Revolución nicaragüense), or Sandinista Revolution (Revolución popular sandinista, ''Sandinista People''s Revolution'') was an armed conflict that took place in the Central American country of Nicaragua between 1961 and 1990. It began with rising opposition to the Somoza dictatorship in the 1960s and 1970s, the overthrow of the dictatorship in 1978–1979, and fighting between the new government and the Contras from 1981 to 1990.', 1978, NULL, NULL, 1990, NULL, NULL, 'year', '1978–1990', 68, 'https://en.wikipedia.org/wiki/Nicaraguan_Revolution'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q16300302', 'April 2014 Nicaragua earthquake', 'The April 2014 Nicaragua earthquake occurred on April 10 at 17:27 local time. The earthquake hit about 50 kilometres (31 mi) north of the town of Managua.', 2014, 4, 10, NULL, NULL, NULL, 'day', '10 April 2014', 37, 'https://en.wikipedia.org/wiki/April_2014_Nicaragua_earthquake'),
  ('Q20720722', '2018 Nicaraguan protests', 'The 2018 Nicaraguan protests began on 18 April 2018 when demonstrators in several cities of Nicaragua began protests against the social security reforms decreed by President Daniel Ortega that increased taxes and decreased benefits. After five days of unrest in which nearly thirty people were killed, Ortega announced the cancellation of the reforms; however, the opposition has grown through the 2014–2018 Nicaraguan protests to denounce Ortega and demand his resignation, becoming one of the largest protests in his government''s history and the deadliest civil conflict since the end of the…', 2018, 4, 18, NULL, NULL, NULL, 'day', '18 April 2018', 52, 'https://en.wikipedia.org/wiki/2018_Nicaraguan_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');
